    "content": "// Variables para el rastreo de la cola/trazado
let prevX, prevY;
const TRAIL_LENGTH = 10;

// Función de configuración p5.js
function setup() {
    // Inicializar el canvas para que ocupe toda la pantalla
    createCanvas(windowWidth, windowHeight);
    // Establecer el modo de color para un mejor control
    colorMode(HSB, 360, 100, 100, 100);
    // Obtener la posición inicial del ratón
    prevX = mouseX;
    prevY = mouseY;
}

// Función que se ejecuta en cada frame
function draw() {
    // Dibujar un fondo semitransparente para crear el efecto de estela/cola
    background(10, 100, 10, 10); // Negro muy transparente

    // Calcula la distancia recorrida desde el último frame (interactividad)
    let speed = dist(prevX, prevY, mouseX, mouseY);

    // Determinar el color basado en la velocidad o la posición (interactividad avanzada)
    // Usamos el ángulo de movimiento para cambiar el matiz del color
    let hue = map(mouseX, 0, width, 0, 360); 
    let saturation = map(mouseY, 0, height, 50, 100);

    // Dibujar el "trazo" o el punto actual
    stroke(hue, saturation, 100, 90);
    strokeWeight(map(speed, 0, 50, 1, 10)); // El grosor varía con la velocidad
    line(prevX, prevY, mouseX, mouseY);
}

// Función para manejar el movimiento del ratón y actualizar las coordenadas anteriores
function mouseMoved() {
    // Actualizamos las posiciones anteriores al moverse el ratón
    prevX = mouseX;
    prevY = mouseY;
}

// Ajustar el canvas si el usuario cambia el tamaño de la ventana
function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}

// Al inicio, forzar un movimiento inicial para que el primer frame se vea bien
function drawMousePos() {
    prevX = mouseX;
    prevY = mouseY;
}

/* Nota: Se añade la función drawMousePos para asegurar que las coordenadas iniciales sean correctas al cargar */"
